"""Chapter VI: all eight numbered theory points and 22 review questions."""
from chapter06_common import *
B=Block('theory')
def add(n,title,statement,answer,rows,p,v,views=None,checks=(),cases=(),collection='theory',printed=None,**kw):
 B.add(n,'single',statement,answer,rows,p,v,views,checks,cases,collection=collection,title=title,printed=printed or ([135] if n<=2 else [136]) if collection=='selfcheck' else printed,**kw)
def question(n,statement,answer,rows,p,v,views=None,checks=(),cases=(),**kw):
 add(n,'Вопрос '+str(n),statement,answer,rows,p,v,views,checks,cases,collection='selfcheck',**kw)
