p,names=regular(5);v=sc(names,poly(names));fan=more(v,segs=[['A','C'],['A','D']]);p['X']=addv(p['B'],subv(p['B'],p['A']));exterior=more(v,'X',[['B','X']],angleArcs=[arc('B','X','C')]);q=dict(A=[0,0],B=[6,0],C=[2,1.5],D=[0,5]);w=sc('ABCD',poly(),lines=[['B','C']])
convex=[row('Что называется выпуклым многоугольником?','Многоугольник выпуклый, если он расположен по одну сторону от каждой прямой, содержащей его сторону. Его внутренний угол образован двумя сторонами при общей вершине и лежит внутри фигуры. Каждый внутренний угол выпуклого многоугольника меньше 180°.','Определение выпуклости.',46),row('Как найти сумму внутренних углов?','Из одной вершины выпуклого n-угольника проведём диагонали ко всем несоседним вершинам. Получаются n −2 треугольника без перекрытий. Их углы вместе составляют все углы многоугольника, поэтому сумма равна (n −2)·180°.','Сумма углов треугольника и разбиение выпуклого многоугольника.',[31,46]),row('Чему равна сумма внешних углов?','Возьмём при каждой вершине один внешний угол, смежный с внутренним. Их сумма равна n·180° −(n −2)·180° =360°. Важно брать ровно один такой угол при каждой вершине.','Смежные углы в сумме дают 180°.',[11,46])]
add(46,'Многоугольники','Выпуклые многоугольники, их внутренние и внешние углы.','Сумма внутренних углов: (n −2)·180°; внешних — 360°.',convex,p,v,[v,fan,exterior],cases=[(q,w,'Невыпуклый четырёхугольник',1)],printed=[121,122])
question(1,'Какой многоугольник называется выпуклым? Какие углы являются его внутренними углами?','Выпуклость проверяется относительно прямой каждой стороны; внутренний угол лежит внутри многоугольника.',[convex[0],row('Как отличить невыпуклый пример?','В дополнительном виде прямая BC оставляет вершины A и D по разные стороны. Поэтому четырёхугольник не удовлетворяет определению выпуклости.','Определение проверяют для каждой стороны, а не одной выбранной.',46)],p,v,cases=[(q,w,'Проверка невыпуклого примера',2)])
question(2,'Выведите формулу суммы углов выпуклого n-угольника.','S =(n −2)·180°.',[row('Сколько треугольников даёт одна вершина?','Из A проведём диагонали ко всем несоседним вершинам: их n −3, а частей-треугольников n −2. Выпуклость гарантирует, что все эти диагонали находятся внутри фигуры.','Диагонали выпуклого многоугольника.',46),convex[1],row('Как проверить формулу на примере?','Для пятиугольника на чертеже получаются 3 треугольника: сумма 3·180° =540°. Для n =3 формула возвращает 180°.','Проверка общей формулы на частных случаях.',[31,46])],p,v,[fan,fan,fan])
question(3,'Докажите, что сумма внешних углов выпуклого многоугольника, взятых по одному при каждой вершине, равна 360°.','360°.',[row('Как связан каждый внешний угол с внутренним?','Они смежные, поэтому внешний угол равен 180° минус внутренний. При каждой вершине берём только один из двух внешних углов.','Свойство смежных углов.',11),convex[2]],p,v,[exterior,exterior])
p=dict(A=[0,0],B=[1,5],C=[7,4],D=[9,0]);v=sc('ABCD',poly());f=more(v,segs=[['A','C'],['B','D']]);g=more(v,segs=[['A','C']]);quad=[row('Как называются элементы четырёхугольника?','A,B,C,D — последовательные вершины. Соседние стороны имеют общую вершину; противоположные — AB и CD, BC и AD. Противоположные вершины — A,C и B,D. Диагонали AC и BD соединяют несоседние вершины.','Определения элементов четырёхугольника.',47),row('Как вычислить сумму углов выпуклого четырёхугольника?','Диагональ AC делит его на ABC и ACD. Сумма углов двух треугольников равна 2·180° =360°; это сумма четырёх внутренних углов.','Сумма углов треугольника.',[31,47]),row('Обязательно ли четырёхугольник выпуклый?','Нет. Определения сторон, вершин и диагоналей действуют и для простого невыпуклого четырёхугольника. Но формулировку о разбиении внутренней области произвольной диагональю нельзя переносить без проверки её положения.','Различие выпуклого и невыпуклого четырёхугольника.',[46,47])]
add(47,'Четырёхугольник','Соседние и противоположные элементы, диагонали и сумма углов.','У выпуклого четырёхугольника сумма углов 360°.',quad,p,v,[f,g,v],cases=[(q,w,'Невыпуклый пример',3)],printed=[122,123])
question(4,'Покажите на четырёхугольнике диагонали, противоположные стороны и противоположные вершины.','Диагонали AC,BD; стороны AB/CD и BC/AD; вершины A/C и B/D.',[quad[0],row('Чем диагональ отличается от стороны?','Сторона соединяет соседние вершины в порядке обхода. Диагональ соединяет противоположные; она не является частью контура четырёхугольника.','Определение диагонали.',47)],p,v,[f,f])
question(5,'Чему равна сумма углов выпуклого четырёхугольника? Обоснуйте ответ.','360°.',[quad[1],row('Как проверить по общей формуле?','Подставим n =4 в (n −2)·180°: получаем (4 −2)·180° =360°.','Формула суммы углов выпуклого многоугольника.',46)],p,v,[g,g])
# Parallelogram properties, including proofs rather than statements alone.
p=parallelogram();p['O']=mid(p['A'],p['C']);v=sc('ABCD',poly());f=more(v,segs=[['A','C']]);g=more(f,'O',[['B','D']]);paradef=row('Что такое параллелограмм?','Параллелограмм — четырёхугольник, у которого противоположные стороны попарно параллельны: AB ∥CD, AD ∥BC. Он выпуклый: относительно прямой любой стороны противоположная сторона находится в одной полуплоскости, и соединяющие отрезки остаются в ней.','Определение и доказательство выпуклости из задачи 478.',[46,48])
parasides=[row('Как доказать равенство противоположных сторон?','Проведём AC. В ABC и CDA сторона AC общая; ∠BAC =∠DCA и ∠BCA =∠DAC как накрест лежащие при параллельных сторонах. По стороне и двум прилежащим углам треугольники равны. Отсюда AB =CD и BC =DA.','Второй признак равенства треугольников.',[19,29]),row('Как доказать равенство противоположных углов?','Из равенства ABC и CDA следует ∠B =∠D. Углы при A и C состоят из попарно равных частей: BAC =DCA и CAD =ACB. Складывая, получаем ∠A =∠C.','Соответственные элементы равных треугольников; сложение углов.',[9,14])]
paradiags=[row('Какие треугольники выделяют диагонали?','Пусть AC и BD пересекаются в O. В AOB и COD стороны AB =CD, а углы BAO =DCO и ABO =CDO равны при параллельных AB и CD.','Противоположные стороны параллелограмма и накрест лежащие углы.',[29,48]),row('Что даёт их равенство?','По стороне и двум прилежащим углам AOB и COD равны. Поэтому AO =CO и BO =DO: обе диагонали делятся точкой пересечения пополам.','Второй признак равенства треугольников.',19)]
add(48,'Параллелограмм','Определение параллелограмма и доказательство его основных свойств.','Противоположные стороны и углы равны; диагонали делятся пополам.',[paradef]+parasides+paradiags,p,v,[v,f,f,g,g],checks=para_checks()+[equal(('A','O'),('O','C')),equal(('B','O'),('O','D'))],printed=[124,125])
question(6,'Дайте определение параллелограмма. Является ли он выпуклым?', 'Да. Это выпуклый четырёхугольник с попарно параллельными противоположными сторонами.',[paradef,row('Почему проверка одной стороны распространяется на остальные?','Для любой стороны противоположная ей параллельная сторона не пересекает её прямую. Соединяющие их концы стороны лежат в той же замкнутой полуплоскости. Такую проверку можно повторить для каждой из четырёх сторон.','Определение выпуклости.',46)],p,v)
question(7,'Докажите равенство противоположных сторон и противоположных углов параллелограмма.','AB =CD, BC =AD, ∠A =∠C, ∠B =∠D.',parasides,p,v,[f,f],checks=para_checks())
question(8,'Докажите, что диагонали параллелограмма делятся точкой пересечения пополам.','AO =OC; BO =OD.',paradiags,p,v,[g,g],checks=[equal(('A','O'),('O','C')),equal(('B','O'),('O','D'))])
signs=[row('Признак 1: одна пара сторон равна и параллельна. Почему этого достаточно?','Пусть AB =CD и AB ∥CD. Проведём AC. В BAC и DCA равны AB и CD, AC общая, BAC =DCA при параллельных прямых. По первому признаку треугольники равны, значит BCA =DAC. Отсюда BC ∥AD. Получены обе пары параллельных сторон.','Первый признак равенства и признак параллельности.',[15,25,29]),row('Признак 2: противоположные стороны попарно равны. Как доказать?','Пусть AB =CD и BC =AD. Треугольники BAC и DCA равны по трём сторонам, включая общую AC. Поэтому BAC =DCA и BCA =DAC; по признакам параллельности AB ∥CD и BC ∥AD.','Третий признак равенства; накрест лежащие углы.',[20,25]),row('Признак 3: диагонали имеют общую середину. Как доказать?','Пусть AO =OC, BO =OD. Треугольники AOB и COD равны по двум сторонам и вертикальному углу; получаем BAO =DCO и AB ∥CD. Аналогично равны BOC и DOA, откуда BC ∥AD. Следовательно четырёхугольник — параллелограмм.','Первый признак равенства и признак параллельности.',[11,15,25])]
add(49,'Признаки параллелограмма','Три достаточных условия, каждое из которых позволяет распознать параллелограмм.','Равные и параллельные противоположные стороны; обе пары равных сторон; общая середина диагоналей.',signs,p,v,[f,f,g],checks=para_checks(),printed=[125,126])
question(9,'Сформулируйте и докажите признаки параллелограмма.','Каждый из трёх признаков доказывается равенством треугольников и параллельностью сторон.',signs,p,v,[f,f,g],checks=para_checks())
