p=trap(9,4,3,1);v=sc('ABCD',poly());iso=trap();iv=sc('ABCD',poly(),equalSegments=[eq('A','B'),eq('C','D')]);right=trap(8,5,4,0);rv=sc('ABCD',poly(),rightAngles=[rt('B','A','D'),rt('A','B','C')]);traprows=[row('Какая фигура называется трапецией?','Трапеция — четырёхугольник, у которого две стороны параллельны, а две другие не параллельны. Здесь AD ∥BC; это основания. AB и CD — боковые стороны.','Определение пункта 50: ровно одна пара параллельных сторон.',50),row('Какие трапеции выделяются особо?','Если боковые стороны равны, трапеция равнобедренная. Если один угол прямой, трапеция прямоугольная; второй угол при той же боковой стороне также прямой, поскольку основания параллельны. Дополнительные виды показывают эти случаи.','Определения и сумма односторонних углов.',[29,50]),row('Почему параллелограмм здесь не трапеция?','У параллелограмма две пары параллельных сторон. Это противоречит принятому в учебнике условию: две другие стороны трапеции не должны быть параллельны.','Сопоставление определений.',[48,50])]
add(50,'Трапеция','Основания, боковые стороны, равнобедренная и прямоугольная трапеции.','Ровно одна пара параллельных сторон; равные боковые стороны или прямой угол задают частные виды.',traprows,p,v,cases=[(iso,iv,'Равнобедренная трапеция',2),(right,rv,'Прямоугольная трапеция',2)],checks=[par('A','D','B','C')],printed=[126])
question(10,'Какой четырёхугольник называется трапецией? Как называются её стороны?','Параллельные стороны — основания; две непараллельные — боковые.',[traprows[0],traprows[2]],p,v)
question(11,'Какая трапеция называется равнобедренной, а какая — прямоугольной?','Равнобедренная имеет равные боковые стороны, прямоугольная — прямой угол.',[traprows[1],row('Что общего у обоих видов?','Они сохраняют основное условие трапеции: основания параллельны, боковые стороны — нет. Равенство оснований вместе с такими углами дало бы другую фигуру.','Определение трапеции.',50)],p,v,cases=[(iso,iv,'Равные боковые стороны',1),(right,rv,'Прямые углы',1)])
p=rect();p['O']=mid(p['A'],p['C']);v=sc('ABCD',poly(),rightAngles=[rt('D','A','B'),rt('A','B','C'),rt('B','C','D'),rt('C','D','A')]);f=more(v,'O',[['A','C'],['B','D']]);rectdef=row('Что такое прямоугольник?','Прямоугольник — параллелограмм, у которого все углы прямые. Поэтому для него верны все свойства параллелограмма: противоположные стороны равны, диагонали делятся пополам.','Определение и наследуемые свойства.',[48,51])
rectdiag=row('Почему диагонали прямоугольника равны?','В BAD и CDA: BA =CD как противоположные стороны, AD общая, углы BAD и CDA прямые. Треугольники равны по двум сторонам и углу между ними, значит BD =AC.','Первый признак равенства треугольников.',15)
rectsign=[row('Как доказать обратный признак?','Пусть ABCD — параллелограмм и AC =BD. В ABC и BAD: AB общая, BC =AD, AC =BD. По трём сторонам треугольники равны, значит ABC =BAD.','Третий признак равенства.',[20,48]),row('Почему равные соседние углы прямые?','Соседние углы параллелограмма в сумме дают 180°. Если они равны, каждый равен 90°. Противоположные им также прямые, поэтому это прямоугольник. Важно, что исходная фигура уже является параллелограммом.','Свойство односторонних углов.',[29,48,51])]
add(51,'Прямоугольник','Прямоугольник, свойство равных диагоналей и обратный признак.','Параллелограмм с равными диагоналями является прямоугольником.',[rectdef,rectdiag]+rectsign,p,v,[v,f,f,f],checks=para_checks()+[equal(('A','C'),('B','D'))],printed=[131,132])
question(12,'Какой четырёхугольник называется прямоугольником?','Параллелограмм со всеми прямыми углами.',[rectdef,row('Достаточен ли один прямой угол в параллелограмме?','Да: противоположный угол равен ему, а соседние дополняют его до 180°. Все четыре угла становятся прямыми.','Задача 502.',[29,48])],p,v)
question(13,'Докажите, что диагонали прямоугольника равны.','AC =BD.',[rectdiag,row('Какие ещё свойства диагоналей сохраняются?','O — их общая середина, поэтому четыре отрезка OA,OB,OC,OD также равны. Это следствие равенства полных диагоналей и свойства параллелограмма.','Свойство диагоналей параллелограмма.',48)],p,v,[f,f],checks=[equal(('A','C'),('B','D'))])
question(14,'Докажите, что параллелограмм с равными диагоналями — прямоугольник.','Равные диагонали дают равные соседние углы; оба прямые.',rectsign,p,v,[f,f],checks=[equal(('A','C'),('B','D'))])
p=parallelogram(5,5,65);p['O']=mid(p['A'],p['C']);v=sc('ABCD',poly(),equalSegments=[eq(*x) for x in poly()]);f=more(v,'O',[['A','C'],['B','D']]);g=more(f,rightAngles=[rt('A','O','B')]);sq=rect(5,5);sq['O']=[2.5,2.5];sv=sc('ABCDO',poly()+[['A','C'],['B','D']],rightAngles=[rt('D','A','B'),rt('A','O','B')]);rhombdef=row('Что такое ромб и квадрат?','Ромб — параллелограмм, у которого все стороны равны. Квадрат — прямоугольник, у которого все стороны равны. Поэтому квадрат является и ромбом, и прямоугольником.','Определения пункта 52.',[51,52])
rhombdiag=[row('Почему диагонали ромба перпендикулярны?','В равнобедренном ABC отрезок BO — медиана, поскольку O — середина AC. Медиана к основанию равнобедренного треугольника является высотой, поэтому BO ⟂AC, то есть BD ⟂AC.','Медиана равнобедренного треугольника и диагонали параллелограмма.',[18,48]),row('Почему они делят углы пополам?','Та же BO — биссектриса угла B. В равнобедренном ADC медиана DO делит угол D пополам. Аналогично, применяя свойство к BAD и BCD с основанием BD, получаем, что AC делит углы A и C пополам.','Медиана к основанию равнобедренного треугольника — биссектриса.',18)]
squareprops=row('Какие свойства получает квадрат?','Все стороны равны, все углы прямые, противоположные стороны параллельны. Диагонали равны как у прямоугольника; перпендикулярны и делят углы пополам как у ромба; имеют общую середину как у параллелограмма.','Совместное применение свойств трёх видов четырёхугольников.',[48,51,52])
add(52,'Ромб и квадрат','Определения и свойства диагоналей ромба и квадрата.','У ромба диагонали перпендикулярны и являются биссектрисами; у квадрата они ещё и равны.',[rhombdef]+rhombdiag+[squareprops],p,v,[v,g,g,g],checks=[equal(*poly()),perp('A','C','B','D')],cases=[(sq,sv,'Квадрат',4,[equal(*poly()),equal(('A','C'),('B','D'))])],printed=[132,133])
question(15,'Какой четырёхугольник называется ромбом?','Параллелограмм с четырьмя равными сторонами.',[rhombdef,row('Нужно ли проверять параллелограмм отдельно, если равны все стороны?','Если дан простой четырёхугольник с четырьмя равными сторонами, обе пары противоположных сторон равны. По признаку он является параллелограммом, а значит ромбом.','Признак по попарно равным противоположным сторонам.',49)],p,v)
question(16,'Докажите, что диагонали ромба перпендикулярны и делят его углы пополам.','AC ⟂BD; AC и BD — биссектрисы соответствующих углов.',rhombdiag,p,v,[g,g],checks=[perp('A','C','B','D')])
question(17,'Что такое квадрат? Перечислите его основные свойства.','Прямоугольник с равными сторонами; равные перпендикулярные диагонали с общей серединой, делящие углы пополам.',[rhombdef,squareprops],sq,sv,checks=[equal(*poly()),equal(('A','C'),('B','D')),perp('A','C','B','D')])
question(18,'Сформулируйте и докажите признаки квадрата.','Ромб с прямым углом; прямоугольник с равными смежными сторонами; четырёхугольник с равными перпендикулярными диагоналями, имеющими общую середину.',[
 row('Признак через ромб.','Если у ромба один угол прямой, по свойствам параллелограмма все углы прямые. Он становится прямоугольником с равными сторонами, то есть квадратом.','Задача 511.',[48,51,52]),
 row('Признак через прямоугольник.','Если у прямоугольника две смежные стороны равны, то вместе с равенством противоположных сторон это даёт равенство всех четырёх. По определению это квадрат.','Определение квадрата.',[48,52]),
 row('Признак через диагонали.','Если диагонали имеют общую середину, четырёхугольник — параллелограмм. Равные диагонали дают прямоугольник, а перпендикулярные — ромб (задача 510а). Вместе это квадрат.','Признаки трёх видов четырёхугольников.',[49,51,52])],sq,sv,checks=[equal(*poly()),equal(('A','C'),('B','D')),perp('A','C','B','D')])
question(19,'Сформулируйте и докажите признаки ромба.','Параллелограмм является ромбом, если его диагонали перпендикулярны или одна диагональ делит его угол пополам.',[
 row('Как доказать признак по перпендикулярным диагоналям?','В параллелограмме AO =OC. При AC ⟂BD прямоугольные AOB и COB равны по двум катетам (OB общий), поэтому AB =BC. Противоположные стороны равны, значит равны все четыре стороны.','Свойство диагоналей и равенство прямоугольных треугольников.',[36,48]),
 row('Как доказать признак по биссектрисе?','Если BAC =CAD, то при BC ∥AD также BCA =CAD. В ABC углы BAC и BCA равны, поэтому AB =BC. Как и в первом случае, все четыре стороны параллелограмма равны.','Параллельные прямые; признак равнобедренного треугольника.',[29,33,48])],p,v,[g,f],checks=[equal(*poly()),perp('A','C','B','D')])
# Central symmetry: examples are separate scenes, not an overcrowded composite.
p=dict(O=[0,0],A=[3,2],B=[-3,-2]);v=sc('OA',[]);f=more(v,'B',[['A','B']],equalSegments=[eq('A','O'),eq('O','B')]);pp=parallelogram();pp['O']=mid(pp['A'],pp['C']);pv=sc('ABCDO',poly()+[['A','C'],['B','D']]);cp=dict(O=[0,0],A=[3,0],B=[-3,0]);cv=sc('OAB',[['A','B']],circles=[circle('O','A')]);lp=dict(O=[0,0],A=[-4,0],B=[4,0]);lv=sc('O',[],lines=[['A','B']]);symdef=row('Какие точки симметричны относительно O?','Точки A и A′ симметричны относительно O, если O — середина AA′: A,O,A′ коллинеарны и OA =OA′. Для A ≠O образ расположен на противоположном луче. Точка O считается симметричной самой себе.','Определение центральной симметрии.',53)
symfigure=row('Когда O является центром симметрии фигуры?','Для каждой точки фигуры её образ при центральной симметрии относительно O должен также принадлежать фигуре. Проверяется вся фигура, а не только несколько выбранных точек.','Определение центра симметрии.',53)
symexamples=row('Какие примеры и ограничения полезно знать?','Окружность имеет центр симметрии в своём центре. У параллелограмма центр — пересечение диагоналей. У прямой центров бесконечно много: любая её точка. Невырожденный треугольник центра симметрии не имеет: пол-оборот должен был бы попарно менять вершины, а нечётное число вершин вынуждает одну остаться в центре, что несовместимо с невырожденностью.','Примеры пункта 53; образ вершин при пол-обороте.',[48,53])
add(53,'Центральная симметрия','Симметрия точек и фигур относительно центра; основные примеры.','O — середина отрезка между точкой и её образом; образ каждой точки симметричной фигуры остаётся в фигуре.',[symdef,symfigure,symexamples],p,v,[f,f,f],checks=[col('A','O','B'),equal(('A','O'),('O','B'))],cases=[(pp,pv,'Параллелограмм',3,[],{}),(cp,cv,'Окружность',3,[],{}),(lp,lv,'Прямая',3,[],{})],labels={'B':'A′'},printed=[133,134])
question(20,'Какие две точки называются симметричными относительно данной точки?','Данная точка — середина отрезка, соединяющего эти точки; центр симметричен самому себе.',[symdef,row('Достаточно ли только равных расстояний?','Нет: две разные точки окружности с центром O равноудалены от O, но симметричны относительно O только противоположные концы диаметра. Нужны одновременно равенство расстояний и расположение на противоположных лучах.','Оба условия определения центральной симметрии.',53)],p,v,[f,f],checks=[col('A','O','B'),equal(('A','O'),('O','B'))],labels={'B':'A′'})
question(21,'Какая фигура называется симметричной относительно данной точки?','Для каждой её точки центрально симметричная точка также принадлежит фигуре.',[symfigure,row('Как проверить это на параллелограмме?','O — общая середина AC и BD, поэтому A и C, B и D меняются местами. Стороны переходят в противоположные стороны, а внутренняя область — в себя. Значит O — центр симметрии всего параллелограмма.','Свойство диагоналей; центральная симметрия отрезка.',[48,53])],pp,pv,checks=[equal(('A','O'),('O','C')),equal(('B','O'),('O','D'))])
tp=dict(A=[0,4],B=[-3,0],C=[3,0],M=[0,0]);tv=sc('ABCM',tri(),lines=[['A','M']]);sq=rect(4,4);sq['O']=[2,2];sv=sc('ABCDO',poly(),lines=[['A','C'],['B','D']])
question(22,'Приведите примеры фигур с: а) осевой симметрией; б) центральной симметрией; в) обоими видами симметрии.','а) равнобедренный треугольник; б) параллелограмм; в) квадрат или окружность.',[
 row('а) Какая фигура имеет ось симметрии?','Равнобедренный треугольник: прямая из вершины через середину основания — серединный перпендикуляр к основанию. Она меняет его концы местами и сохраняет вершину и обе боковые стороны.','Свойства равнобедренного треугольника; отражение.',[18,44,45]),
 row('б) Какая фигура имеет центр симметрии?','Параллелограмм: точка пересечения диагоналей меняет противоположные вершины и стороны местами. Дополнительный вид показывает пример.','Диагонали делятся пополам.',[48,53]),
 row('в) Какая фигура имеет оба вида?','Квадрат имеет четыре оси: две диагонали и две прямые через середины противоположных сторон; центр — пересечение диагоналей. Окружность имеет осью каждую прямую через её центр, а сам центр является и центром симметрии. Вопрос не требует, чтобы примеры в а и б обладали только одним видом симметрии.','Свойства квадрата и окружности.',[21,45,52,53])],tp,tv,cases=[(pp,pv,'б) Параллелограмм',2),(sq,sv,'в) Квадрат',3),(cp,cv,'в) Окружность',3)])
